@Component("payment-handler")
@ProcessingGroup("payment-processing-group")
public class PaymentEventHandler {
	
	// core constructor
	PaymentEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreatePaymentEvent
     */
    @EventHandler
    public void handle( CreatePaymentEvent event) {
        entityManager.persist(new Payment(event.getPaymentId(), event.getPaymentReference(), event.getAmount(), event.getPaymentDate(), event.getInvoice(), event.getBillingAccount(), event.getPolicy(), event.getMethod(), event.getStatus()));
    }

    /*
     * @param	event UpdatePaymentEvent
     */
    @EventHandler
    public Payment handle( UpdatePaymentEvent event) {
    	entityManager.merge(new Payment(event.getPaymentId(), event.getPaymentReference(), event.getAmount(), event.getPaymentDate(), event.getInvoice(), event.getBillingAccount(), event.getPolicy(), event.getMethod(), event.getStatus()));
    }
    
    /*
     * @param	event DeletePaymentEvent
     */
    @EventHandler
    public void on( DeletePaymentEvent event) {
    	Payment entity = new Payment();
   
    	// ------------------------------------------
    	// apply the PaymentId
    	// ------------------------------------------
    	entity.setPaymentId( event.getPaymentId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final PaymentRepository paymentEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(PaymentEventHandler.class.getName());

}
